chrome.runtime.onMessage.addListener((r,e,a)=>{if(r.type==="OPEN_TAB")return chrome.tabs.create({url:r.url,active:r.active}).then(()=>a({ok:!0})).catch(t=>{a({ok:!1,error:t instanceof Error?t.message:String(t)})}),!0;if(r.type==="HTTP_POST_FORM")return fetch(r.url,{method:"POST",headers:r.headers,body:r.data}).then(async t=>{a({ok:!0,status:t.status,responseText:await t.text()})}).catch(t=>{a({ok:!1,error:t instanceof Error?t.message:String(t)})}),!0});
